import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        if (n > m) {
            int t = n;
            n = m;
            m = t;
        }
        if (n == 1) {
            int x = m % 6;
            if (x <= 3) {
                System.out.println(m - x);
            } else if (x == 4) {
                System.out.println(m - 2);
            } else {
                System.out.println(m - 1);
            }
            return;
        }
        if (n <= 5 && m <= 30) {
            int[][][] answer = new int[m + 1][n + 1][1 << (3 * n)];
            for (int[][] layer : answer) {
                for (int[] row : layer) {
                    java.util.Arrays.fill(row, -1);
                }
            }
            System.out.println(go(0, 0, 0, n, m, answer));
        } else {
            System.out.println(n * m - (n * m) % 2);
        }
    }

    private static int go(int row, int col, int mask, int n, int m, int[][][] answer) {
        if (answer[row][col][mask] != -1) {
            return answer[row][col][mask];
        }
        if (row == m) {
            return answer[row][col][mask] = (mask == 0) ? 0 : Integer.MIN_VALUE;
        }
        if (col == n) {
            return answer[row][col][mask] = go(row + 1, 0, mask, n, m, answer);
        }
        if ((mask & 1) == 1) {
            return answer[row][col][mask] = go(row, col + 1, mask >> 1, n, m, answer);
        }
        int res = go(row, col + 1, mask >> 1, n, m, answer);
        res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (3 * n - 1)), n, m, answer) + 2);
        if (col != 0 && ((mask >> (2 * n - 1)) & 1) == 0) {
            res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (2 * n - 2)), n, m, answer) + 2);
        }
        if (col != n - 1 && ((mask >> (2 * n + 1)) & 1) == 0) {
            res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (2 * n)), n, m, answer) + 2);
        }
        if (col >= 2 && ((mask >> (n - 2)) & 1) == 0) {
            res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (n - 3)), n, m, answer) + 2);
        }
        if (col < n - 1 && ((mask >> (n + 2)) & 1) == 0) {
            res = Math.max(res, go(row, col + 1, (mask >> 1) + (1 << (n + 1)), n, m, answer) + 2);
        }
        return answer[row][col][mask] = res;
    }
}
